function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || !operations.length || operations.length !== args.length) return 'operations and arguments need the same, non-zero length.';
  if (operations[0] !== 'MovieRentingSystem') return 'The first operation must be MovieRentingSystem.';
  if (operations.length - 1 > 100000) return 'At most 10^5 calls are allowed.';
  const [n, entries] = args[0];
  if (!Number.isInteger(n) || n < 1 || n > 300000) return 'n is between 1 and 3 * 10^5.';
  if (!Array.isArray(entries) || entries.length < 1 || entries.length > 100000) return 'entries needs 1 to 10^5 items.';
  const rented = new Map();
  for (const entry of entries) {
    if (!Array.isArray(entry) || entry.length !== 3 || !entry.every(Number.isInteger)) return 'Each entry is [shop, movie, price].';
    const [shop, movie, price] = entry;
    if (shop < 0 || shop >= n) return 'Each shop is between 0 and n - 1.';
    if (movie < 1 || movie > 10000 || price < 1 || price > 10000) return 'movie and price are between 1 and 10^4.';
    if (rented.has(shop + ',' + movie)) return 'A shop has at most one copy of each movie.';
    rented.set(shop + ',' + movie, false);
  }
  for (let i = 1; i < operations.length; i++) {
    const op = operations[i], a = args[i];
    if (op === 'search') {
      if (!Number.isInteger(a[0]) || a[0] < 1 || a[0] > 10000) return 'search takes a movie between 1 and 10^4.';
    } else if (op === 'rent' || op === 'drop') {
      const key = a[0] + ',' + a[1];
      if (!rented.has(key)) return op + ' needs a shop that owns that movie.';
      if (op === 'rent' && rented.get(key)) return 'rent needs a copy that is on the shelf.';
      if (op === 'drop' && !rented.get(key)) return 'drop needs a copy that is rented out.';
      rented.set(key, op === 'rent');
    } else if (op !== 'report') return 'Unknown operation ' + op + '.';
  }
  return null;
}

