class MovieRentingSystem {
  constructor(n, entries) {
    this.prices = new Map();
    this.unrented = new Map();
    this.rented = [];
    for (const [shop, movie, price] of entries) {
      this.prices.set(`${shop},${movie}`, price);
      if (!this.unrented.has(movie)) {
        this.unrented.set(movie, []);
      }
      this.unrented.get(movie).push([price, shop]);
    }
    for (const copies of this.unrented.values()) {
      copies.sort((a, b) => this.compare(a, b));
    }
  }

  compare(a, b) {
    for (let i = 0; i < a.length; i++) {
      if (a[i] !== b[i]) return a[i] - b[i];
    }
    return 0;
  }

  position(list, item) {
    let lo = 0;
    let hi = list.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (this.compare(list[mid], item) < 0) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    return lo;
  }

  search(movie) {
    const copies = this.unrented.get(movie) || [];
    return copies.slice(0, 5).map(([price, shop]) => shop);
  }

  rent(shop, movie) {
    const price = this.prices.get(`${shop},${movie}`);
    const copies = this.unrented.get(movie);
    copies.splice(this.position(copies, [price, shop]), 1);
    const item = [price, shop, movie];
    this.rented.splice(this.position(this.rented, item), 0, item);
  }

  drop(shop, movie) {
    const price = this.prices.get(`${shop},${movie}`);
    const item = [price, shop, movie];
    this.rented.splice(this.position(this.rented, item), 1);
    const copies = this.unrented.get(movie);
    copies.splice(this.position(copies, [price, shop]), 0, [price, shop]);
  }

  report() {
    return this.rented.slice(0, 5).map(([price, shop, movie]) => [shop, movie]);
  }
}

