class MovieRentingSystem {
  constructor(n, entries) {
    this.copies = entries.map(([shop, movie, price]) => ({ shop, movie, price, out: false }));
  }
  find(shop, movie) {
    return this.copies.find(c => c.shop === shop && c.movie === movie);
  }
  search(movie) {
    return this.copies.filter(c => c.movie === movie && !c.out).sort((a, b) => a.price - b.price || a.shop - b.shop).slice(0, 5).map(c => c.shop);
  }
  rent(shop, movie) { this.find(shop, movie).out = true; }
  drop(shop, movie) { this.find(shop, movie).out = false; }
  report() {
    return this.copies.filter(c => c.out).sort((a, b) => a.price - b.price || a.shop - b.shop || a.movie - b.movie).slice(0, 5).map(c => [c.shop, c.movie]);
  }
}

