function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const pick = list => list[Math.floor(rand() * list.length)];
  const large = size === 'large';
  const n = large ? int(50, 300) : int(1, 4);
  const movieCount = large ? int(5, 60) : int(1, 4);
  // Few distinct prices create the ties that the ordering rules must break.
  const maxPrice = large ? (rand() < 0.5 ? 20 : 10000) : int(1, 5);
  const target = large ? int(800, 1500) : int(1, 8);
  const entries = [], owned = new Set();
  for (let tries = 0; entries.length < target && tries < target * 4; tries++) {
    const shop = int(0, n - 1), movie = int(1, movieCount);
    if (owned.has(shop + ',' + movie)) continue;
    owned.add(shop + ',' + movie);
    entries.push([shop, movie, int(1, maxPrice)]);
  }
  const operations = ['MovieRentingSystem'], args = [[n, entries]];
  const shelf = entries.map(([shop, movie]) => [shop, movie]), out = [];
  const move = (from, to) => {
    const i = Math.floor(rand() * from.length);
    const copy = from[i];
    from[i] = from[from.length - 1];
    from.pop();
    to.push(copy);
    return copy;
  };
  const steps = large ? 499 : int(1, 14);
  for (let i = 0; i < steps; i++) {
    const roll = rand();
    if (roll < 0.35 && shelf.length) { operations.push('rent'); args.push(move(shelf, out)); }
    else if (roll < 0.5 && out.length) { operations.push('drop'); args.push(move(out, shelf)); }
    else if (roll < 0.75) { operations.push('search'); args.push([rand() < 0.9 ? int(1, movieCount) : movieCount + int(1, 3)]); }
    else { operations.push('report'); args.push([]); }
  }
  return [operations, args];
}
